let gradShaderSrc = `precision highp float;

// x,y coordinates, given from the vertex shader
varying vec2 vTexCoord;

// the canvas contents, given from filter()
uniform sampler2D tex0;
// other useful information from the canvas
uniform vec2 texelSize;
uniform vec2 canvasSize;
// a custom variable from this sketch
// uniform float gamma;
uniform vec4 clrFg1;
uniform vec4 clrFg2;
uniform vec4 clrFg3;
uniform vec4 clrFg4;
uniform vec4 clrBg1;
uniform vec4 clrBg2;
uniform vec4 clrBg3;
uniform vec4 clrBg4;

void main() {
	// get the color at current pixel
	vec4 color = texture2D(tex0, vTexCoord);
	// set the output color
	float f = (color.r + color.g + color.b) / 3.;
	// gamma: color = pow((color / 1.0),(1. / gamma));
	// dark/brighness: color *= db;

	// fg mix
	vec4 clrFgL = mix(clrFg1, clrFg4, fract(vTexCoord.y));
	vec4 clrFgR = mix(clrFg2, clrFg3, fract(vTexCoord.y));
	vec4 clrFG = mix(clrFgL, clrFgR, fract(vTexCoord.x));

	// bg mix
	vec4 clrBgL = mix(clrBg1, clrBg4, fract(vTexCoord.y));
	vec4 clrBgR = mix(clrBg2, clrBg3, fract(vTexCoord.y));
	vec4 clrBG = mix(clrBgL, clrBgR, fract(vTexCoord.x));

	// output based on grayscale
	gl_FragColor = mix(clrBG, clrFG, f);
}`;

